import{_ as i,c as s,a1 as e,o as t}from"./chunks/framework.EpXtiTQS.js";const k=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"yatori-go-core/v3/faq.md","filePath":"yatori-go-core/v3/faq.md"}'),o={name:"yatori-go-core/v3/faq.md"};function n(l,a,h,r,d,p){return t(),s("div",null,a[0]||(a[0]=[e('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="基础概念" tabindex="-1">基础概念 <a class="header-anchor" href="#基础概念" aria-label="Permalink to &quot;基础概念&quot;">​</a></h2><h3 id="errunsupported-是什么意思" tabindex="-1"><code>ErrUnsupported</code> 是什么意思？ <a class="header-anchor" href="#errunsupported-是什么意思" aria-label="Permalink to &quot;`ErrUnsupported` 是什么意思？&quot;">​</a></h3><p>平台不支持当前操作。例如微伴只有登录，调用 <code>client.Courses</code> 就会返回包装了 <code>ErrUnsupported</code> 的错误。</p><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> errors.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Is</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(err, yatori.ErrUnsupported) {</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">	// 平台没有这个功能</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>不要用 <code>err == yatori.ErrUnsupported</code>，因为适配器会加上平台和操作上下文。</p><h3 id="capabilities-和-errunsupported-有什么区别" tabindex="-1"><code>Capabilities()</code> 和 <code>ErrUnsupported</code> 有什么区别？ <a class="header-anchor" href="#capabilities-和-errunsupported-有什么区别" aria-label="Permalink to &quot;`Capabilities()` 和 `ErrUnsupported` 有什么区别？&quot;">​</a></h3><ul><li><code>Capabilities()</code>：调用前预判，告诉你平台实现了哪些能力；</li><li><code>ErrUnsupported</code>：调用后兜底，确认平台确实不支持。</li></ul><p>两者配合使用，详见 <a href="/yatori-docs/yatori-go-core/v3/capabilities.html">能力与错误</a>。</p><h3 id="capabilities-能判断当前账号有没有作业吗" tabindex="-1"><code>Capabilities()</code> 能判断当前账号有没有作业吗？ <a class="header-anchor" href="#capabilities-能判断当前账号有没有作业吗" aria-label="Permalink to &quot;`Capabilities()` 能判断当前账号有没有作业吗？&quot;">​</a></h3><p>不能。能力位只表示“平台实现了这个接口”。课程没有作业时，<code>Works</code> 返回空切片和 <code>nil</code> 错误。</p><h3 id="capabilities-能判断有没有登录吗" tabindex="-1"><code>Capabilities()</code> 能判断有没有登录吗？ <a class="header-anchor" href="#capabilities-能判断有没有登录吗" aria-label="Permalink to &quot;`Capabilities()` 能判断有没有登录吗？&quot;">​</a></h3><p>不能。未登录时调用 <code>Courses</code> 会返回 <code>ErrNotLoggedIn</code>。</p><h2 id="登录" tabindex="-1">登录 <a class="header-anchor" href="#登录" aria-label="Permalink to &quot;登录&quot;">​</a></h2><h3 id="为什么登录失败" tabindex="-1">为什么登录失败？ <a class="header-anchor" href="#为什么登录失败" aria-label="Permalink to &quot;为什么登录失败？&quot;">​</a></h3><p>按顺序检查：</p><ol><li>账号密码是否正确；</li><li>平台是否需要 <code>Account.URL</code>（英华、海旗）；</li><li>平台是否需要 <code>Account.School</code>（微伴）；</li><li>网络/代理是否可用；</li><li>是否触发验证码或风控；</li><li>是否需要使用 Cookie/Token 登录。</li></ol><h3 id="英华-海旗为什么要填-url" tabindex="-1">英华/海旗为什么要填 URL？ <a class="header-anchor" href="#英华-海旗为什么要填-url" aria-label="Permalink to &quot;英华/海旗为什么要填 URL？&quot;">​</a></h3><p>这两个平台的接口地址与学校站点绑定。英华的 URL 必须是<strong>登录后的站点地址</strong>，不是登录页；海旗的 URL 是学校站点根地址。</p><h3 id="cookie-token-怎么填" tabindex="-1">Cookie/Token 怎么填？ <a class="header-anchor" href="#cookie-token-怎么填" aria-label="Permalink to &quot;Cookie/Token 怎么填？&quot;">​</a></h3><p>统一填到 <code>Account.Cookie</code>：</p><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Account: </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yatori</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Account</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	Username: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;账号&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	Password: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;密码&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	Cookie:   </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;cookie_or_token&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span></code></pre></div><p>支持情况见 <a href="/yatori-docs/yatori-go-core/v3/platforms.html">平台说明</a>。</p><h3 id="智慧树为什么不能-login" tabindex="-1">智慧树为什么不能 <code>Login</code>？ <a class="header-anchor" href="#智慧树为什么不能-login" aria-label="Permalink to &quot;智慧树为什么不能 `Login`？&quot;">​</a></h3><p>智慧树只有扫码登录。请使用 <code>yatori.QRCodeLogin</code> 接口：</p><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">qr </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> client.(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yatori</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">QRCodeLogin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">imageBase64, token, _ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> qr.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">QRCode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ctx)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">session, _ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> qr.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">WaitQRCode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ctx, token)</span></span></code></pre></div><h2 id="学习" tabindex="-1">学习 <a class="header-anchor" href="#学习" aria-label="Permalink to &quot;学习&quot;">​</a></h2><h3 id="为什么-study-一次就完成了" tabindex="-1">为什么 <code>Study</code> 一次就完成了？ <a class="header-anchor" href="#为什么-study-一次就完成了" aria-label="Permalink to &quot;为什么 `Study` 一次就完成了？&quot;">​</a></h3><p>不同平台的粒度不同：</p><ul><li>学习通/英华/CQIE/TTCDW：提交一次进度；</li><li>职教云/课堂行/WeLearn：一次调用完成整个节点；</li><li>青书：开始/提交一次学习会话；</li><li>海旗：提交一次百分比，Fast 模式直接完成。</li></ul><p>以 <code>StudyResult.Completed</code> 为准，不要假设所有平台都需要循环。</p><h3 id="study-的-position-是什么单位" tabindex="-1"><code>Study</code> 的 <code>Position</code> 是什么单位？ <a class="header-anchor" href="#study-的-position-是什么单位" aria-label="Permalink to &quot;`Study` 的 `Position` 是什么单位？&quot;">​</a></h3><p><code>time.Duration</code>，例如 <code>60 * time.Second</code>。动态调用时也支持 <code>&quot;60s&quot;</code> 或 <code>60</code>（秒）。</p><h3 id="为什么-tree-返回的章节没有子节点" tabindex="-1">为什么 <code>Tree</code> 返回的章节没有子节点？ <a class="header-anchor" href="#为什么-tree-返回的章节没有子节点" aria-label="Permalink to &quot;为什么 `Tree` 返回的章节没有子节点？&quot;">​</a></h3><p>可能原因：</p><ul><li>章节未开放；</li><li>章节下确实没有任务点；</li><li>平台接口临时失败（适配器会记录 debug 日志并返回空 children）；</li><li>该平台只返回扁平节点。</li></ul><h3 id="学习通的直播-讨论节点为什么返回-errunsupported" tabindex="-1">学习通的直播/讨论节点为什么返回 <code>ErrUnsupported</code>？ <a class="header-anchor" href="#学习通的直播-讨论节点为什么返回-errunsupported" aria-label="Permalink to &quot;学习通的直播/讨论节点为什么返回 `ErrUnsupported`？&quot;">​</a></h3><p>V3 目前只统一了视频、音频、文档、外链等主要节点。直播/讨论的接口差异较大，尚未纳入统一 <code>Study</code>，后续版本会补齐。</p><h2 id="作业与考试" tabindex="-1">作业与考试 <a class="header-anchor" href="#作业与考试" aria-label="Permalink to &quot;作业与考试&quot;">​</a></h2><h3 id="works-返回空切片-是失败吗" tabindex="-1"><code>Works</code> 返回空切片，是失败吗？ <a class="header-anchor" href="#works-返回空切片-是失败吗" aria-label="Permalink to &quot;`Works` 返回空切片，是失败吗？&quot;">​</a></h3><p>不是。表示课程没有作业，或者当前账号没有可见作业。<code>err</code> 为 <code>nil</code>。</p><h3 id="dowork-的-answersource-怎么选" tabindex="-1"><code>DoWork</code> 的 <code>AnswerSource</code> 怎么选？ <a class="header-anchor" href="#dowork-的-answersource-怎么选" aria-label="Permalink to &quot;`DoWork` 的 `AnswerSource` 怎么选？&quot;">​</a></h3><table tabindex="0"><thead><tr><th>来源</th><th>适用场景</th></tr></thead><tbody><tr><td><code>AnswerSourceAI</code></td><td>已配置 <code>Options.AI</code></td></tr><tr><td><code>AnswerSourceBank</code></td><td>已配置 <code>Options.QuestionBank</code></td></tr><tr><td><code>AnswerSourceBuiltin</code></td><td>平台随题返回答案，例如青书、海旗</td></tr><tr><td><code>AnswerSourceManual</code></td><td>你自己填充答案</td></tr></tbody></table><h3 id="青书为什么不使用-ai" tabindex="-1">青书为什么不使用 AI？ <a class="header-anchor" href="#青书为什么不使用-ai" aria-label="Permalink to &quot;青书为什么不使用 AI？&quot;">​</a></h3><p>青书的作业接口会随题返回参考答案，适配器直接使用平台答案，所以 <code>AnswerSource</code> 对青书不生效。</p><h3 id="海旗的-dowork-为什么处理了所有作业" tabindex="-1">海旗的 <code>DoWork</code> 为什么处理了所有作业？ <a class="header-anchor" href="#海旗的-dowork-为什么处理了所有作业" aria-label="Permalink to &quot;海旗的 `DoWork` 为什么处理了所有作业？&quot;">​</a></h3><p>海旗的作业/考试接口按课程节点聚合，适配器沿用旧实现的行为：一次处理该课程下所有相关任务，而不是只处理传入的那一份。调用后请以 <code>AnswerResult.Raw</code> / 日志为准。</p><h3 id="enaae-的考试为什么不能提交" tabindex="-1">ENAAE 的考试为什么不能提交？ <a class="header-anchor" href="#enaae-的考试为什么不能提交" aria-label="Permalink to &quot;ENAAE 的考试为什么不能提交？&quot;">​</a></h3><p>ENAAE 目前只实现了考试列表，<code>DoExam</code> 返回 <code>ErrUnsupported</code>。</p><h2 id="配置与资源" tabindex="-1">配置与资源 <a class="header-anchor" href="#配置与资源" aria-label="Permalink to &quot;配置与资源&quot;">​</a></h2><h3 id="为什么运行目录会出现-assets-目录" tabindex="-1">为什么运行目录会出现 <code>assets</code> 目录？ <a class="header-anchor" href="#为什么运行目录会出现-assets-目录" aria-label="Permalink to &quot;为什么运行目录会出现 `assets` 目录？&quot;">​</a></h3><p>部分平台沿用旧实现的相对路径：</p><ul><li>验证码图片：<code>./assets/code/</code></li><li>职教云辅助 exe：<code>./assets/tencentCollect.exe</code>、<code>./assets/tencentPowSolve.exe</code></li><li>OCR 模型：<code>./assets/*.onnx</code>、<code>./assets/onnxruntime_*.dll</code></li><li>学习通人脸素材：<code>./assets/faces/</code></li></ul><p>新 SDK 已经改为按需释放，但路径仍然是相对当前工作目录的。请确保运行目录可写。</p><p><code>Options.WorkDir</code> 目前是预留字段，旧动作还没有全部迁移到它。</p><h3 id="可以关闭日志吗" tabindex="-1">可以关闭日志吗？ <a class="header-anchor" href="#可以关闭日志吗" aria-label="Permalink to &quot;可以关闭日志吗？&quot;">​</a></h3><p>适配器自身使用 <code>Options.Logger</code>；传 <code>yatori.NopLogger()</code> 可以关闭适配器日志。旧平台动作仍会向标准输出打印部分日志，这是历史行为。</p><h3 id="代理怎么配置" tabindex="-1">代理怎么配置？ <a class="header-anchor" href="#代理怎么配置" aria-label="Permalink to &quot;代理怎么配置？&quot;">​</a></h3><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Options: </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yatori</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Options</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	ProxyURL: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://127.0.0.1:7890&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span></code></pre></div><p>旧缓存只接受主机和端口，适配器会解析 URL 后传入。带用户名密码的代理支持有限，建议使用本地无认证代理。</p><h3 id="ai-配置怎么写" tabindex="-1">AI 配置怎么写？ <a class="header-anchor" href="#ai-配置怎么写" aria-label="Permalink to &quot;AI 配置怎么写？&quot;">​</a></h3><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Options: </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yatori</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Options</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	AI: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yatori</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">AIConfig</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">		Type:   yatori.AIDeepSeek,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">		Model:  </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;deepseek-chat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">		APIKey: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sk-xxxx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	},</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span></code></pre></div><p><code>Type</code> 可用值见 <a href="/yatori-docs/yatori-go-core/v3/getting-started.html#_5-4-ai-配置">快速开始</a>。</p><h3 id="外部题库怎么接" tabindex="-1">外部题库怎么接？ <a class="header-anchor" href="#外部题库怎么接" aria-label="Permalink to &quot;外部题库怎么接？&quot;">​</a></h3><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Options: </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yatori</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Options</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	QuestionBank: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yatori</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">QuestionBankConfig</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">		URL: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://127.0.0.1:8083&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	},</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span></code></pre></div><p>题库协议见 <a href="/yatori-docs/bank-interface-api/docs.html">题库对接文档</a>。</p><h2 id="并发与稳定性" tabindex="-1">并发与稳定性 <a class="header-anchor" href="#并发与稳定性" aria-label="Permalink to &quot;并发与稳定性&quot;">​</a></h2><h3 id="可以多个-goroutine-共用一个-client-吗" tabindex="-1">可以多个 goroutine 共用一个 Client 吗？ <a class="header-anchor" href="#可以多个-goroutine-共用一个-client-吗" aria-label="Permalink to &quot;可以多个 goroutine 共用一个 Client 吗？&quot;">​</a></h3><p>不建议。一个 <code>Client</code> 对应一个账号/会话，方法内部会串行访问底层状态。多账号请为每个账号创建独立 <code>Client</code>。</p><h3 id="多账号并发多少合适" tabindex="-1">多账号并发多少合适？ <a class="header-anchor" href="#多账号并发多少合适" aria-label="Permalink to &quot;多账号并发多少合适？&quot;">​</a></h3><p>从 1–3 个账号开始，观察平台限流和封控情况。不要无限并发，也不要在同一账号上多开。</p><h3 id="登录失效怎么办" tabindex="-1">登录失效怎么办？ <a class="header-anchor" href="#登录失效怎么办" aria-label="Permalink to &quot;登录失效怎么办？&quot;">​</a></h3><p>重新调用 <code>client.Login(ctx)</code>：</p><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> errors.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Is</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(err, yatori.ErrNotLoggedIn) {</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> err </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> client.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Login</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ctx); err </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> nil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">		return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> err</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	}</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>部分平台的动作内部会自动重登，但不要完全依赖它。</p><h3 id="可以把-client-存到数据库吗" tabindex="-1">可以把 <code>Client</code> 存到数据库吗？ <a class="header-anchor" href="#可以把-client-存到数据库吗" aria-label="Permalink to &quot;可以把 `Client` 存到数据库吗？&quot;">​</a></h3><p>不可以。<code>Client</code> 持有网络会话和指针，不能序列化。需要持久化时保存：</p><ul><li>平台；</li><li>账号；</li><li><code>Session.Cookie</code> / <code>Session.Token</code>；</li><li>课程/节点的 <code>Extra</code>。</li></ul><h2 id="编译与依赖" tabindex="-1">编译与依赖 <a class="header-anchor" href="#编译与依赖" aria-label="Permalink to &quot;编译与依赖&quot;">​</a></h2><h3 id="gcc-executable-file-not-found" tabindex="-1"><code>gcc: executable file not found</code> <a class="header-anchor" href="#gcc-executable-file-not-found" aria-label="Permalink to &quot;`gcc: executable file not found`&quot;">​</a></h3><p>需要安装 GCC/MinGW-w64，并确保 <code>gcc</code> 在 <code>PATH</code> 中。Windows 推荐使用 MinGW-w64。</p><h3 id="cgo-enabled-0-可以吗" tabindex="-1"><code>CGO_ENABLED=0</code> 可以吗？ <a class="header-anchor" href="#cgo-enabled-0-可以吗" aria-label="Permalink to &quot;`CGO_ENABLED=0` 可以吗？&quot;">​</a></h3><p>不可以。部分依赖需要 CGO。请设置：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CGO_ENABLED=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span></code></pre></div><h3 id="为什么二进制这么大" tabindex="-1">为什么二进制这么大？ <a class="header-anchor" href="#为什么二进制这么大" aria-label="Permalink to &quot;为什么二进制这么大？&quot;">​</a></h3><p>根包会注册全部平台适配器，因此会链接所有平台依赖（包括 OCR、SQLite、ONNX Runtime）。这是“一个入口支持全部平台”的代价。</p><p>当前版本必须导入根包，因此会链接全部平台依赖。后续版本会提供按平台拆分的公开 driver 包，届时可以只链接需要的平台。</p><h2 id="迁移" tabindex="-1">迁移 <a class="header-anchor" href="#迁移" aria-label="Permalink to &quot;迁移&quot;">​</a></h2><h3 id="还能导入-api-或-aggregation-吗" tabindex="-1">还能导入 <code>api/*</code> 或 <code>aggregation/*</code> 吗？ <a class="header-anchor" href="#还能导入-api-或-aggregation-吗" aria-label="Permalink to &quot;还能导入 `api/*` 或 `aggregation/*` 吗？&quot;">​</a></h3><p>不能。它们已经移动到 <code>internal/</code>，外部模块无法导入。请使用根包 <code>yatori</code>。</p><h3 id="global-config-还能用吗" tabindex="-1"><code>global.Config</code> 还能用吗？ <a class="header-anchor" href="#global-config-还能用吗" aria-label="Permalink to &quot;`global.Config` 还能用吗？&quot;">​</a></h3><p>可以编译，但已标记 <code>Deprecated</code>。新代码请把配置显式传给 <code>yatori.New</code>。</p><h3 id="utils-yatoricoreinit-还需要调用吗" tabindex="-1"><code>utils.YatoriCoreInit()</code> 还需要调用吗？ <a class="header-anchor" href="#utils-yatoricoreinit-还需要调用吗" aria-label="Permalink to &quot;`utils.YatoriCoreInit()` 还需要调用吗？&quot;">​</a></h3><p>新 SDK 不需要。适配器会在需要时初始化 OCR/辅助资源。只有你仍在直接使用旧 <code>api</code>/<code>aggregation</code> 代码时才需要。</p><h2 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h2><h3 id="如何查看平台原始数据" tabindex="-1">如何查看平台原始数据？ <a class="header-anchor" href="#如何查看平台原始数据" aria-label="Permalink to &quot;如何查看平台原始数据？&quot;">​</a></h3><p>用 <code>Course.Raw</code>、<code>Node.Raw</code>、<code>Work.Raw</code>、<code>Exam.Raw</code>。它们只在当前进程有效，不要序列化。</p><h3 id="如何提交问题" tabindex="-1">如何提交问题？ <a class="header-anchor" href="#如何提交问题" aria-label="Permalink to &quot;如何提交问题？&quot;">​</a></h3><p>请附上：</p><ul><li>平台；</li><li>脱敏后的错误信息；</li><li>复现代码；</li><li><code>go version</code>、操作系统；</li><li>是否使用代理/Cookie/AI。</li></ul><p>不要提交真实账号密码、Cookie、Token、API Key。</p>',101)]))}const E=i(o,[["render",n]]);export{k as __pageData,E as default};
